code_sketch:
/* production: the boundary sits behind a function pointer */
static int (*now_ms)(void) = real_now_ms;       /* test overrides this */
int is_midnight(void) { return format(now_ms()) == MIDNIGHT; }

/* test */
static int fake_now(void) { return 0; }
void test_midnight(void **state) {
    now_ms = fake_now;                          /* install the double */
    assert_true(is_midnight());
    now_ms = real_now_ms;                       /* restore in teardown */
}
